cat > /private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/BlueskyUITap/SearchTests.swift <<'EOF'
import XCTest

final class SearchTests: XCTestCase {
  func testOpenCaturdaySearch() {
    let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
    let openButton = springboard.alerts.buttons["Open"]
    if openButton.waitForExistence(timeout: 2) { openButton.tap() }

    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
    app.activate()
    let search = app.buttons["Search"]
    if search.waitForExistence(timeout: 10) { search.tap() }
    else { XCTFail("Search tab not found. UI: \(app.debugDescription)"); return }

    let field = app.textFields.firstMatch
    if !field.waitForExistence(timeout: 5) { XCTFail("Search field not found. UI: \(app.debugDescription)"); return }
    field.tap()
    field.typeText("#caturday")
    field.typeText("\n")
    XCTAssertTrue(app.staticTexts["Top"].waitForExistence(timeout: 10), "Top tab should be visible. UI: \(app.debugDescription)")
  }
}
EOF

